/**
 * The path of each subject type with a `url`: block entities, `subjects`
 * and app table subjects.
 * @public
 */
export const urls = {
  product: () => "/shop",
  deal: () => "/crm/deals",
  employee: () => "/people",
  company: (v: { readonly id: string | number }) => `/crm/contacts/${String(v.id)}`,
  person: (v: { readonly id: string | number }) => `/crm/contacts/${String(v.id)}`,
  workItem: () => "/work",
  customer: (v: { readonly id: string | number }) => `/customers/${String(v.id)}`,
  application: () => "/people/hiring",
  project: (v: { readonly id: string | number }) => `/projects/${String(v.id)}`,
  task: (v: { readonly projectId: string | number }) => `/projects/${String(v.projectId)}`,
} as const;

/** The realtime topics the blocks broadcast on, with their placeholders filled. @public */
export const topics = {
  aiChat: () => "ai-chat",
  aiChatList: () => "ai-chats",
  announcements: () => "announcements",
  inbox: () => "inbox",
  messaging: () => "messages",
  notifications: (v: { readonly userId: string }) => `notifications:${String(v.userId)}`,
  reactions: () => "reactions",
} as const;

/** Object paths in each bucket, from `buckets.<name>.path`. @public */
export const paths = {
  customerLogos: (v: { readonly organizationId: string; readonly customerId: string; readonly version: string }) => `${String(v.organizationId)}/${String(v.customerId)}/logo/${String(v.version)}.webp`,
  avatars: (v: { readonly userId: string; readonly version: string; readonly ext: string }) => `${String(v.userId)}/avatar-${String(v.version)}.${String(v.ext)}`,
} as const;
